import{_ as t,c as a,o as e,ag as i}from"./chunks/framework.DCv_I274.js";const k=JSON.parse('{"title":"RESTful APIs","description":"","frontmatter":{},"headers":[],"relativePath":"fundamentals/restful-apis.md","filePath":"fundamentals/restful-apis.md","lastUpdated":null}'),n={name:"fundamentals/restful-apis.md"};function o(r,s,d,h,l,p){return e(),a("div",null,[...s[0]||(s[0]=[i(`<h1 id="restful-apis" tabindex="-1">RESTful APIs <a class="header-anchor" href="#restful-apis" aria-label="Permalink to &quot;RESTful APIs&quot;">​</a></h1><p>An <strong>API</strong> (Application Programming Interface) is a way for programs to talk to each other. A <strong>web API</strong> does it over HTTP, usually with JSON. <strong>REST</strong> is a set of conventions that makes web APIs predictable.</p><h2 id="the-core-idea-resources" tabindex="-1">The core idea: resources <a class="header-anchor" href="#the-core-idea-resources" aria-label="Permalink to &quot;The core idea: resources&quot;">​</a></h2><p>Think in <strong>nouns</strong> (resources), not actions. The URL names the resource; the <strong>HTTP method</strong> says what to do with it.</p><table tabindex="0"><thead><tr><th>Action</th><th>Method &amp; URL</th><th>Success status</th></tr></thead><tbody><tr><td>List campuses</td><td><code>GET /api/v1/campuses</code></td><td>200</td></tr><tr><td>Read one campus</td><td><code>GET /api/v1/campuses/5</code></td><td>200 (404 if missing)</td></tr><tr><td>Create a campus</td><td><code>POST /api/v1/campuses</code></td><td>201 (or 200)</td></tr><tr><td>Change some fields</td><td><code>PATCH /api/v1/campuses/5</code></td><td>200</td></tr><tr><td>Replace completely</td><td><code>PUT /api/v1/campuses/5</code></td><td>200</td></tr><tr><td>Delete</td><td><code>DELETE /api/v1/campuses/5</code></td><td>200 or 204</td></tr></tbody></table><p>Avoid verbs in URLs: not <code>POST /createCampus</code> or <code>GET /getCampuses</code>.</p><h3 id="nested-resources-and-actions" tabindex="-1">Nested resources and actions <a class="header-anchor" href="#nested-resources-and-actions" aria-label="Permalink to &quot;Nested resources and actions&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET  /api/v1/user-groups/4/members        members *of* group 4</span></span>
<span class="line"><span>PUT  /api/v1/user-groups/4/permissions    replace the permission set of group 4</span></span>
<span class="line"><span>POST /api/v1/applications/12/approve      an action that isn&#39;t plain CRUD</span></span>
<span class="line"><span>GET  /api/v1/user-groups/stats            a computed summary</span></span></code></pre></div><p>When an operation really is an action (approve, publish, logout), a <code>POST</code> to a sub-path with a verb is the accepted exception.</p><h2 id="principles" tabindex="-1">Principles <a class="header-anchor" href="#principles" aria-label="Permalink to &quot;Principles&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Principle</th><th>Meaning</th><th>In practice</th></tr></thead><tbody><tr><td><strong>Stateless</strong></td><td>every request carries everything needed (e.g. the token)</td><td>no server memory of &quot;the previous request&quot;</td></tr><tr><td><strong>Uniform interface</strong></td><td>same patterns everywhere</td><td>same URL style, same envelope, same status codes</td></tr><tr><td><strong>Client–server</strong></td><td>frontend and backend evolve separately</td><td>the API doesn&#39;t care whether the client is Vue, mobile or a script</td></tr><tr><td><strong>Cacheable</strong></td><td>responses say whether they may be cached</td><td><code>Cache-Control</code> headers</td></tr><tr><td><strong>Layered</strong></td><td>proxies / load balancers can sit in between</td><td><code>TrustProxies</code>, rate limits</td></tr></tbody></table><h2 id="designing-good-endpoints" tabindex="-1">Designing good endpoints <a class="header-anchor" href="#designing-good-endpoints" aria-label="Permalink to &quot;Designing good endpoints&quot;">​</a></h2><h3 id="naming" tabindex="-1">Naming <a class="header-anchor" href="#naming" aria-label="Permalink to &quot;Naming&quot;">​</a></h3><ul><li>Plural, lowercase, kebab-case nouns: <code>/user-groups</code>, <code>/campuses</code>.</li><li>IDs in the path, options in the query string: <code>/campuses/5</code>, <code>/campuses?search=main&amp;page=2</code>.</li><li>JSON keys in <code>snake_case</code>: <code>access_expires_in</code>, <code>is_active</code>.</li></ul><h3 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h3><p>Prefix URLs with a version: <code>/api/v1/...</code>. When you must break the contract (rename a field, change a type), publish <code>/api/v2/...</code> and keep <code>v1</code> working until clients move.</p><p><strong>Breaking changes:</strong> removing or renaming a field, changing a type, making an optional field required, changing a status code. <strong>Non-breaking:</strong> adding an optional field or a new endpoint.</p><h3 id="pagination-search-filter-sort" tabindex="-1">Pagination, search, filter, sort <a class="header-anchor" href="#pagination-search-filter-sort" aria-label="Permalink to &quot;Pagination, search, filter, sort&quot;">​</a></h3><p>Lists are always paginated. These docs use:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/v1/campuses?page=2&amp;per_page=10&amp;search=main&amp;active=1&amp;so=n,desc</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Param</th><th>Meaning</th></tr></thead><tbody><tr><td><code>page</code>, <code>per_page</code></td><td>which slice</td></tr><tr><td><code>search</code></td><td>free-text search</td></tr><tr><td>filter keys (<code>active</code>, ...)</td><td>exact-match filters</td></tr><tr><td><code>so=key,direction</code></td><td>sort</td></tr></tbody></table><h3 id="one-response-envelope" tabindex="-1">One response envelope <a class="header-anchor" href="#one-response-envelope" aria-label="Permalink to &quot;One response envelope&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Campuses fetched successfully&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;data&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [ </span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;meta&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: { </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;total&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">42</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;success&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;message&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;The name field is required.&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><p>The client can always read <code>success</code> and <code>message</code>, whatever the endpoint.</p><h3 id="status-codes-carry-meaning" tabindex="-1">Status codes carry meaning <a class="header-anchor" href="#status-codes-carry-meaning" aria-label="Permalink to &quot;Status codes carry meaning&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Situation</th><th>Status</th></tr></thead><tbody><tr><td>Validation failed</td><td>422 + first error in <code>message</code></td></tr><tr><td>Business rule broken (&quot;group still has members&quot;)</td><td>400</td></tr><tr><td>Not logged in / token expired</td><td>401</td></tr><tr><td>Logged in but not allowed</td><td>403</td></tr><tr><td>Not found</td><td>404</td></tr><tr><td>Conflict / race</td><td>409</td></tr><tr><td>Too many requests</td><td>429</td></tr><tr><td>Bug</td><td>500, never with a stack trace in production</td></tr></tbody></table><p>Never answer <code>200</code> with <code>&quot;success&quot;: false</code> for an error the client must react to: status codes are what HTTP clients, proxies and monitoring understand.</p><h3 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h3><p>APIs send credentials <strong>on every request</strong>, usually <code>Authorization: Bearer &lt;access token&gt;</code>. Tokens are short-lived; a refresh mechanism gets a new one. Details: <a href="/architecture/authentication">Authentication</a>.</p><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><p>An API nobody can discover is useless. These docs generate an <strong>OpenAPI</strong> description automatically from the code with Scramble (<a href="/foundations/11-api-docs">API docs</a>), browsable at <code>/docs/api</code>.</p><h2 id="calling-an-api" tabindex="-1">Calling an API <a class="header-anchor" href="#calling-an-api" aria-label="Permalink to &quot;Calling an API&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8000/api/v1/campuses</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$TOKEN</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Accept: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;code&quot;:&quot;MAIN&quot;,&quot;name&quot;:&quot;Main Campus&quot;,&quot;is_active&quot;:true}&#39;</span></span></code></pre></div><p>The same request as a VS Code REST Client <code>.http</code> file:</p><div class="language-http vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">http</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">POST</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> http://localhost:8000/api/v1/campuses</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Authorization</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> Bearer {{token}}</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Accept</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">Content-Type</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> application/json</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{ </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;code&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MAIN&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Main Campus&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;is_active&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span></code></pre></div><div class="tip custom-block"><p class="custom-block-title">Always send <code>Accept: application/json</code></p><p>Without it, Laravel treats the call as a browser request: validation errors become redirects and errors become HTML pages.</p></div><p>Next: <a href="/fundamentals/full-stack">Full-stack architectures</a></p>`,37)])])}const u=t(n,[["render",o]]);export{k as __pageData,u as default};
